"use server";

// Generated by philote from component SlotPicker's calls. Do not edit.
import * as api from "@/lib/api";
import { message } from "@/lib/form";
import type { Booking } from "@/lib/types";
import { needViewer } from "@/lib/viewer";

// BookResult is what a call to book did: what it made, or the
// error to show.
export type BookResult = { ok: true; value: Booking } | { ok: false; error: string };

// book calls the book endpoint as the viewer.
export async function book(input: { slot: string }): Promise<BookResult> {
    const viewer = await needViewer();
    const result = await api.book({ client: viewer.id, slot: input.slot });
    return result.ok ? { ok: true, value: result.value } : { ok: false, error: message(result.error) };
}
